import{d as g,C as t,o as b,c,j as a,a as r,E as o,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第七十一章","description":"从知不知、不知知的对照读认知限度，辨病病的动词与名词及圣人不病之意。","frontmatter":{"title":"道德经第七十一章","description":"从知不知、不知知的对照读认知限度，辨病病的动词与名词及圣人不病之意。","category":"guide","aliases":["道德经第七十一章","老子第七十一章","dao de jing chapter 71"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-71.md","filePath":"daoism/dao-de-jing/chapter-71.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-71.md"},y=g({...m,setup(u){const i=[{id:"knowing-what-is-not-known",label:"知不知，上",showLabel:!0,sentences:[[{text:"知",glossary:"zhi"},"不",{text:"知",glossary:"zhi"},"，",{text:"上",glossary:"shang"},"；"]],note:["【白话】知道自己还有不知道的地方，是较高明的认识态度。这里先从承认所知有边界来理解知不知，而不把不知道本身当成成就。","【读法】上用于评说这种态度较好，不是说身居上位。承认不知之后，仍可以继续求证和学习；重点是不给尚未明白的事情冒充一个已知答案。"]},{id:"mistaking-limited-knowledge-for-certainty",label:"不知知，病",showLabel:!0,sentences:[["不",{text:"知",glossary:"zhi"},{text:"知",glossary:"zhi"},"，",{text:"病",glossary:"bing"},"。"]],note:["【白话】不知道却自以为知道，是一种弊病。依王弼的解释，尤其要警惕：不明白自己的知有不足凭任之处，却把它当作足够的依靠。","【王弼注择要】「不知知之不足任，则病也。」注将问题放在不知知的限度，不只是承认某一项事实暂时不清楚。","【读法】前一句白话先列通常的不知而自以为知读法，再说明所据王注的重心。两者都可提示认识的限度，但不能因此推成一切知识都无用。"]},{id:"regarding-the-fault-as-a-fault",label:"夫唯病病",showLabel:!0,sentences:[["夫唯",{text:"病",glossary:"bing-regard"},{text:"病",glossary:"bing"},"，是以不",{text:"病",glossary:"bing"},"。"]],note:["【白话】正因为能把这种弊病看作弊病、认真正视它，所以才不陷于这种弊病。前一个病是以为病，后一个病是所指的弊病。","【读法】本句把开头的认识态度推进到自我检查。发现自己不知道，若仍只是口头谦虚而不改变判断方式，便还没有走到病病这一层。"]},{id:"the-sage-and-recognized-limits",label:"圣人不病",showLabel:!0,sentences:[["圣人不",{text:"病",glossary:"bing"},"，以其",{text:"病",glossary:"bing-regard"},{text:"病",glossary:"bing"},"，是以不",{text:"病",glossary:"bing"},"。"]],note:["【白话】圣人没有这种弊病，正因为他把这种弊病当作需要正视的问题，所以不被它困住。不病的理由，仍回到以其病病。","【读法】这里没有说圣人掌握了一切知识。末句重复不病，是为了把圣人的认识态度与前文相接；病在本章指认识上的弊病，不是身体永不患病。","【读法】所据本章仅在不知知病之后见上述王注，其余段落依经文解释，不补造逐句古注。"]}],n=[{id:"zhi",term:"知",sense:2,pinyin:["zhī"]},{id:"shang",term:"上",sense:2},{id:"bing",term:"病",sense:1},{id:"bing-regard",term:"病",sense:2}];return(x,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return b(),c("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第七十一章",tabindex:"-1"},[r("道德经第七十一章 "),a("a",{class:"header-anchor",href:"#道德经第七十一章","aria-label":'Permalink to "道德经第七十一章"'},"​")],-1)),o(s,{title:"知道自己有所不知，为什么反而是上",summary:"本章不比较谁知道得最多，而是追问人怎样对待自己的不知。知不知与不知知先构成对照，随后用病病说明：能把认识上的弊病当作问题，才可能不被它遮蔽。王弼特别指出，要知道知本身也有不足凭任之处。",points:[{label:"先读",text:"知不知先按知道自己有所不知理解，上是较高明的评价。"},{label:"再辨",text:"病病前一病作动词，后一病是弊病，不是两个身体疾病的叠加。"},{label:"后看",text:"圣人不病承接以其病病，所强调的是面对认知局限的态度。"}],hint:"知在本章读 zhī，上读 shàng，病读 bìng。病病要区分以为弊病与弊病本身两个用法。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[r("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:i,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[r("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"知不知，上；不知知，病。",tone:"先辨认识的态度",guide:"知道自己的边界，与把有限的知当作足够的凭依，构成全章起点。"},{text:"夫唯病病，是以不病。",tone:"两个病各有用法",guide:"以为弊病的动词，作用于弊病这一名词，落在能否正视问题。"},{text:"圣人不病，以其病病，是以不病。",tone:"圣人也从自检说起",guide:"不病有其理由，不靠自称高明或声称无所不知。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[r("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:n}),e[4]||(e[4]=p("",15))])}}});export{_ as __pageData,y as default};
